import { mkdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

const evidenceDir = process.env.DETRAN_STACK_STATE_DIR ?? '/tmp/detran-stack';
const authHeaders = {
  authorization: 'Bearer local',
  'x-detran-tenant-id': '00000000-0000-7000-8000-00000000a001',
};

function evidenceRow(row) {
  const { persona, fixture, ...safe } = row;
  return {
    ...safe,
    ...(persona ? { principal: 'local-principal' } : {}),
    ...(fixture ? { fixture: 'test-fixture' } : {}),
  };
}

async function jsonRequest(fetchImpl, url, init = {}) {
  try {
    const response = await fetchImpl(url, init);
    const contentType = response.headers.get('content-type') ?? '';
    let body;
    try {
      body = await response.json();
    } catch {
      return { response, reason: 'invalid_json' };
    }
    return { response, body, contentType };
  } catch {
    return { reason: 'backend_unreachable' };
  }
}

function nonEmpty(value) {
  if (Array.isArray(value)) return value.length > 0;
  return (
    value &&
    typeof value === 'object' &&
    Object.keys(value).length > 0 &&
    (!Array.isArray(value.items) || value.items.length > 0)
  );
}

export async function runSmoke({ targets, fetchImpl = fetch }) {
  const rows = [];
  const add = (row) => rows.push(row);
  const check = async (target, url, expected = 200, init) => {
    const result = await jsonRequest(fetchImpl, url, init);
    if (!result.response)
      return add({
        target,
        result: 'failed',
        reason: result.reason,
        status: 0,
      });
    if (result.response.status !== expected)
      return add({
        target,
        result: 'failed',
        reason:
          result.response.status === 401
            ? 'unauthorized'
            : result.response.status === 403
              ? 'forbidden'
              : `unexpected_status_${result.response.status}`,
        status: result.response.status,
      });
    if (result.reason)
      return add({
        target,
        result: 'failed',
        reason: result.reason,
        status: result.response.status,
      });
    return add({
      target,
      result: 'passed',
      reason: 'ok',
      status: result.response.status,
      body: result.body,
    });
  };

  for (const path of targets.backend.health)
    await check(`backend.${path.slice(1)}`, `${targets.backend.url}${path}`);
  for (const service of [targets.senatran, targets.sefaz])
    for (const path of service.health)
      await check(
        service === targets.sefaz ? 'sefaz.health' : 'senatran.health',
        `${service.url}${path}`,
      );
  for (const frontend of targets.frontends) {
    await check(`frontend.${frontend.name}.root`, `${frontend.rootUrl}/`);
    const result = await jsonRequest(
      fetchImpl,
      `${frontend.proxyUrl}${frontend.readPath}`,
      { headers: authHeaders },
    );
    const row = {
      target: `frontend.${frontend.name}.proxy`,
      persona: frontend.persona,
      fixture: frontend.fixture,
    };
    if (!result.response)
      add({
        ...row,
        result: 'failed',
        reason: 'backend_unreachable',
        status: 0,
      });
    else if (result.response.status !== 200)
      add({
        ...row,
        result: 'failed',
        reason:
          result.response.status === 401
            ? 'unauthorized'
            : result.response.status === 403
              ? 'forbidden'
              : `unexpected_status_${result.response.status}`,
        status: result.response.status,
      });
    else if (result.reason)
      add({ ...row, result: 'failed', reason: result.reason, status: 200 });
    else if (!nonEmpty(result.body))
      add({ ...row, result: 'failed', reason: 'empty_json', status: 200 });
    else if (
      frontend.expectedTenant &&
      result.body.tenantId &&
      result.body.tenantId !== frontend.expectedTenant
    )
      add({ ...row, result: 'failed', reason: 'tenant_mismatch', status: 200 });
    else add({ ...row, result: 'passed', reason: 'ok', status: 200 });
  }
  const pec = { state: targets.pec?.state ?? 'not_built_r0031' };
  for (const probe of targets.ch ?? []) {
    const result = await jsonRequest(
      fetchImpl,
      `${probe.proxyUrl ?? targets.frontends[0].proxyUrl}${probe.path}`,
      {
        method: 'POST',
        headers: { ...authHeaders, 'content-type': 'application/json' },
        body: JSON.stringify(probe.body ?? {}),
      },
    );
    const row = {
      target: `ch.${probe.name}`,
      persona: probe.persona,
      fixture: probe.fixture,
    };
    if (!result.response)
      add({
        ...row,
        result: 'blocked_before_adapter',
        reason: 'backend_unreachable',
        status: 0,
      });
    else if (result.response.status !== 503)
      add({
        ...row,
        result: 'blocked_before_adapter',
        reason: `unexpected_status_${result.response.status}`,
        status: result.response.status,
      });
    else if (result.reason)
      add({
        ...row,
        result: 'blocked_before_adapter',
        reason: result.reason,
        status: 503,
      });
    else if (probe.message && result.body?.message !== probe.message)
      add({
        ...row,
        result: 'blocked_before_adapter',
        reason: 'adapter_message_mismatch',
        status: 503,
        adapterMessage: result.body?.message,
      });
    else
      add({
        ...row,
        result: 'passed',
        reason: 'adapter_unconfigured',
        status: 503,
        adapterMessage: result.body?.message,
      });
  }
  const complete = rows.every((row) => row.result === 'passed');
  const report = {
    complete,
    pec,
    rows: rows.map(({ body: _body, ...row }) => row),
  };
  await mkdir(evidenceDir, { recursive: true });
  const safe = { ...report, rows: report.rows.map(evidenceRow) };
  await writeFile(
    join(evidenceDir, 'smoke-report.json'),
    `${JSON.stringify(safe, null, 2)}\n`,
  );
  await writeFile(
    join(evidenceDir, 'smoke-report.txt'),
    safe.rows
      .map(
        (row) => `${row.target}\t${row.result}\t${row.reason}\t${row.status}`,
      )
      .join('\n') + '\n',
  );
  return report;
}

const defaultTargets = {
  frontends: [
    ['portal', 4200, '/v1/portal/complaints/records', 'AUDITOR'],
    ['rait', 4201, '/v1/inf/rait/cases', 'rait-coordinator'],
    ['dashboard', 4202, '/v1/dashboard/alerts', 'dash-operator'],
    ['teat', 4203, '/v1/ops/field/operations', 'field-agent'],
  ].map(([name, port, readPath, persona]) => ({
    name,
    rootUrl: `http://127.0.0.1:${port}`,
    proxyUrl: `http://127.0.0.1:${port}`,
    readPath,
    persona,
    fixture: `${name}-test-fixture`,
  })),
  backend: { url: 'http://127.0.0.1:3001', health: ['/healthz', '/readyz'] },
  senatran: { url: 'http://127.0.0.1:3000', health: ['/health'] },
  sefaz: { url: 'http://127.0.0.1:3999', health: ['/health'] },
  pec: { state: 'not_built_r0031' },
  ch: [],
};
if (import.meta.url === `file://${process.argv[1]}`) {
  const report = await runSmoke({ targets: defaultTargets });
  process.exitCode = report.complete ? 0 : 1;
}

