      const layer = await this.gate.open(tx, req, {
        route: 'GET alerts',
        policy: 'dashboard:alert:read',
        requiredLayer: 'N1',
        requestedLayer: query.layer,
        ceiling: 'N1',
        app: query.app,
        filters: query,
      });
      const { layer: _layer, ...filters } = query;
