        tx,
        this.gate.tenantId(),
        filters,
        layer.servedLayer,
        layer.domains,
      );
      const freshness = await this.catalog.freshnessFor(
        tx,
        this.gate.tenantId(),
        listed.indicatorCodes,
      );
      await this.gate.record(tx, layer, listed.items.length);
      return {
        items: listed.items,
        page: listed.page,
        pageSize: listed.pageSize,
        total: listed.total,
        meta: {
          freshness,
          page: listed.page,
          pageSize: listed.pageSize,
          total: listed.total,
          ...(query.unit !== undefined ? { sourcePending: 'OD-D38' } : {}),
        },
      };
    });
  }

